css:
:root {
  --primary: #1f6feb;
  --primary-hover: #1a5bc2;
  --bg: #0d1726;
  --bg-alt: #12263a;
  --text: #e8f0ff;
  --text-secondary: #a7bbd6;
  --border: #24405f;
  --card-bg: #132742;
  --success: #2dd4bf;
  --warning: #fbbf24;
  --error: #f87171;
}

body {
  background: radial-gradient(circle at 12% 20%, rgba(31, 111, 235, 0.18), transparent 30%),
              radial-gradient(circle at 80% 0%, rgba(45, 212, 191, 0.12), transparent 32%),
              #0b1422;
  color: var(--text);
}

.header, .board-header, .card-detail-header {
  background: linear-gradient(120deg, rgba(31, 111, 235, 0.85), rgba(45, 212, 191, 0.75));
  border-bottom: 2px solid rgba(255, 255, 255, 0.1);
  color: #0b1422;
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.3);
}

.brand {
  letter-spacing: 0.04em;
  font-weight: 800;
}

.card, .card-detail {
  background: var(--card-bg);
  border: 1px solid var(--border);
  box-shadow: 0 12px 30px rgba(10, 20, 34, 0.35);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.card:hover {
  transform: translateY(-2px);
  box-shadow: 0 16px 40px rgba(10, 20, 34, 0.45);
}

button, .btn {
  border-radius: 10px;
  font-weight: 700;
  border: 1px solid rgba(255, 255, 255, 0.2);
  background: linear-gradient(135deg, rgba(31, 111, 235, 0.9), rgba(45, 212, 191, 0.85));
  color: #0b1422;
}

.tag, .tag-chip {
  background: rgba(45, 212, 191, 0.15);
  color: var(--text);
  border: 1px solid rgba(45, 212, 191, 0.35);
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, rgba(31, 111, 235, 0.8), rgba(45, 212, 191, 0.8));
  border-radius: 12px;
}
